import pytest

from bedrock_protocol import v975, v1001

# generated by gophertunnel de090ae:
# &packet.LevelSoundEvent{SoundType: 258, Position: mgl32.Vec3{1, 2, 3}, ExtraData: -1,
#     EntityType: "minecraft:pig", BabyMob: true, DisableRelativeVolume: false, EntityUniqueID: 7,
#     FireAtPosition: protocol.Option(mgl32.Vec3{4, 5, 6})}
V975 = bytes.fromhex(
    "82020000803f0000004000004040010d6d696e6563726166743a7069670100070000000000000001000080400000a0400000c040"
)

# generated by gophertunnel 654cd5f:
# &packet.LevelSoundEvent{SoundType: "block.bell.hit", Position: mgl32.Vec3{1, 2, 3}, ExtraData: -1,
#     EntityType: "minecraft:pig", BabyMob: true, DisableRelativeVolume: false, EntityUniqueID: 7,
#     FireAtPosition: protocol.Option(mgl32.Vec3{4, 5, 6})}
V1001 = bytes.fromhex(
    "0e626c6f636b2e62656c6c2e6869740000803f0000004000004040010d6d696e6563726166743a70696701000700000000000000"
    "01000080400000a0400000c040"
)

GOLDENS = [
    pytest.param(
        v975.LevelSoundEventPacket(
            event_id=v975.LevelSoundEvent.BELL,
            pos=v975.Vec3(x=1, y=2, z=3),
            data=-1,
            actor_identifier="minecraft:pig",
            is_baby=True,
            is_global=False,
            actor=7,
            fire_at_position=v975.Vec3(x=4, y=5, z=6),
        ),
        V975,
        id="v975",
    ),
    pytest.param(
        v1001.LevelSoundEventPacket(
            sound_event="block.bell.hit",
            pos=v1001.Vec3(x=1, y=2, z=3),
            data=-1,
            actor_identifier="minecraft:pig",
            is_baby=True,
            is_global=False,
            actor=7,
            fire_at_position=v1001.Vec3(x=4, y=5, z=6),
        ),
        V1001,
        id="v1001",
    ),
]


@pytest.mark.parametrize("version", [v975, v1001])
def test_level_sound_event_is_packet_123(version):
    assert version.packets[123] is version.LevelSoundEventPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_level_sound_event_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_level_sound_event_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_the_993_change_is_confined_to_the_leading_sound_field():
    assert V975[2:] == V1001[15:]
